const allPhraseCatalog = { ...phraseCatalog, ...workspacePhraseCatalog };
const englishCatalogKeys = new Map<string, DeskMessageKey>(
  (Object.keys(catalog.en) as DeskMessageKey[]).map((key) => [catalog.en[key], key] as const),
);
const phraseTemplates = Object.entries(allPhraseCatalog)
  .filter(([template]) => template.includes("{"))
  .map(([template, translations]) => {
    const names = template.match(/\{([^}]+)\}/g) || [];
    const parts = template.split(/\{[^}]+\}/g);
    const expression = new RegExp(
      `^${parts.map((part) => part.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")).join("([\\s\\S]*?)")}$`,
    );
    return { names, translations, expression };
  });

export function translateDeskPhrase(
  language: LanguageCode | string | undefined,
  phrase: string,
  replacements: Record<string, string | number> = {},
): string {
  const selected = language && language in catalog ? language as LanguageCode : "en";
  const localeIndex = phraseLanguageOrder.indexOf(selected as typeof phraseLanguageOrder[number]);
  const source = phrase.trim();
  if (!source) return phrase;
  const leading = phrase.match(/^\s*/)?.[0] || "";
  const trailing = phrase.match(/\s*$/)?.[0] || "";
  let translated = source;
  if (localeIndex >= 0) {
    const direct = allPhraseCatalog[source];
    const messageKey = englishCatalogKeys.get(source);
    if (direct) {
      translated = direct[localeIndex];
    } else if (messageKey) {
      translated = translateDesk(selected, messageKey);
    } else {
      for (const template of phraseTemplates) {
        const match = source.match(template.expression);
        if (!match) continue;
        translated = template.translations[localeIndex];
        template.names.forEach((name, index) => {
          translated = translated.replaceAll(name, match[index + 1]);
        });
        break;
      }
    }
  }
  for (const [key, value] of Object.entries(replacements)) {
    translated = translated.replaceAll(`{${key}}`, String(value));
  }
  return `${leading}${translated}${trailing}`;
}

export function localizeApiError(
  language: LanguageCode,
  message: string,
  status: number,
  reference?: string,
): string {
  const translated = language === "en"
    ? message || translateDesk("en", "error.request")
    : translateDesk(language, status === 401 ? "error.401" : status === 400 ? "error.400" :
      status === 403 ? "error.403" : status === 404 ? "error.404" : status === 409 ? "error.409" :
        status === 429 ? "error.429" : status >= 500 ? "error.500" : "error.request");
  return reference ? `${translated} ${translateDesk(language, "error.reference")}: ${reference}` : translated;
}
